\begin{align*}
\prod^n_{k=1} k^{2k-n-1} & = \frac{1}{(n!)^{n+1}} \cdot \prod_{k=1}^n k^{2k} = \frac{1^2 \cdot 2^4 \cdot \cdots \cdot n^{2n}}{(n!)^{n+1}}
& = \frac{(n!)^2\left(\frac{n!}{1!}\right)^2\left(\frac{n!}{2!}\right)^2 \cdots \left(\frac{n!}{{n-1}!}\right)^2}{(n!)^{n+1}}
&= 1\cdot \left(\frac{n!}{(1!)^2}\right) \left(\frac{n!}{(2!)^2}\right) \cdots \left(\frac{n!}{(n-1)!^2}\right)
&= \frac{n!^{n-1}}{(1!2!\dots (n-1)!)^2}
&= \frac{n!}{1!(n-1)!} \cdot \frac{n!}{2!(n-2)!} \cdot \cdots \cdot \frac{n!}{(n-1)!1!}
&= \prod_{k=1}^{n-1}\binom{n}{k}
\end{align*}
which is a product of integers and hence is an integer itself.

